using System.Windows;using OncaPDV.Domain;using OncaPDV.Infrastructure;namespace OncaPDV.Desktop;public partial class ReceiveCreditWindow:Window{private readonly CreditView _account;public decimal Amount{get;private set;}public PaymentMethod Method{get;private set;}public string? Notes=>string.IsNullOrWhiteSpace(NotesBox.Text)?null:NotesBox.Text.Trim();public ReceiveCreditWindow(CreditView a){_account=a;InitializeComponent();Customer.Text=a.Customer;Balance.Text=$"Saldo atual: {a.Balance:C}";AmountBox.Text=a.Balance.ToString("N2");}private void Confirm_Click(object s,RoutedEventArgs e){if(!decimal.TryParse(AmountBox.Text,out var value)||value<=0||value>_account.Balance){MessageBox.Show("Valor inválido.");return;}Amount=value;Method=MethodBox.SelectedIndex switch{0=>PaymentMethod.Cash,1=>PaymentMethod.Pix,2=>PaymentMethod.Debit,_=>PaymentMethod.Credit};DialogResult=true;}}
